window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-231030c70bd5ffec"]={"versions": [{"id": "FIG-231030c70bd5ffec", "releases": ["R18-03_R1.4.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Informelles Architektur- und Datenflussdiagramm (Deployment-Pipeline-Modell) der AUTOSAR Adaptive Platform (Release R18-03 / AP 1.4.0).\n</li><li><strong>Kontext &amp; Zweck:</strong> Veranschaulichung des zweistufigen Software-Packaging- und Deployment-Konzepts im Kontext des Functional Clusters <em>Update and Configuration Management (UCM)</em>. Es definiert den hierarchischen Kapselungs- und Übergabeprozess von Software-Paketen (Software Packages) ausgehend von der Zulieferer-Toolchain (<em>Vendor</em>) über die Integrationsstufe des Fahrzeugherstellers (<em>OEM</em>) bis hin zur Zielplattform (<em>Target ECU</em>) via OTA (Over-The-Air) oder Diagnose-Schnittstellen (Diagnostic Management / DM).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Software Package (SW Pkg) Grundstruktur:</strong>\n<ul class=\"fig-list\"><li><strong>Updates (Payload):</strong> Binärdateien, Bibliotheken, Konfigurationsdaten, Adaptive Application Executables sowie Execution- und Machine-Manifeste (<code>.arxml</code>).\n</li><li><strong>Meta data:</strong> Maschinenlesbares Software Package Manifest (Metadaten zu Name, Version, Abhängigkeiten, Hashwerten, Signatur/Sicherheitszertifikaten und Target-Zuordnung).\n</li></ul>\n</li><li><strong>Tooling-Domäne (Off-Board / Entwicklungsumgebung):</strong>\n<ul class=\"fig-list\"><li><strong>Vendor:</strong> Pack-Werkzeug des Tiers/Zulieferers. Schnürt das <em>Vendor Package</em> als komprimiertes/strukturiertes Archiv (<code>zip</code> oder <code>tar</code>), bestehend aus Payload und Vendor-Manifest.\n</li><li><strong>OEM:</strong> Integrations-Toolchain des Fahrzeugherstellers. Kapselt ein oder mehrere Vendor-Pakete in ein übergeordnetes <em>OEM Package</em> (<code>zip</code>/<code>tar</code>), angereichert mit fahrzeugweiten Metadaten, Rollout-Richtlinien und OEM-Signaturen.\n</li></ul>\n</li><li><strong>Target-Domäne (On-Board Adaptive Machine):</strong>\n<ul class=\"fig-list\"><li><strong>OTA/DM (Client-Instanz):</strong> Lokaler Empfänger auf dem Steuergerät (z. B. OTA-Client oder Diagnostic Management / DoIP / UDS RoutineControl). \n</li><li>Verarbeitet zunächst das äußere OEM-Paket, validiert die Kapselung und extrahiert das/die eingebettete(n) Vendor-Paket(e) zur Übergabe an die Ziel-Laufzeitumgebung.\n</li></ul>\n</li><li><strong>Beziehungen &amp; Kapselungsmodell:</strong>\n<ul class=\"fig-list\"><li>Kapselungsrelation (Container-in-Container): <code>OEM Package</code> enthält als Nutzlast mindestens ein <code>Vendor Package</code> (1 … n).\n</li><li>Formatkonvention: Beide Ebenen nutzen standardisierte Archivformate (<code>.zip</code> bzw. <code>.tar</code>), jeweils geschützt durch integre Metadaten/Signaturen.\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Vendor Packaging (Off-Board):</strong> \n<ul class=\"fig-list\"><li>Kompilierung und Bündelung der Software-Artefakte mit dem Software Package Manifest in ein <em>Vendor Package</em> (<code>zip/tar</code>).\n</li></ul>\n</li><li><strong>OEM Ingestion &amp; Repackaging (Off-Board):</strong> \n<ul class=\"fig-list\"><li>Validierung des Vendor-Pakets gegen OEM-Richtlinien.\n</li><li>Einbettung in das <em>OEM Package</em> (<code>zip/tar</code>) inklusive übergeordneter Kampagnen-Metadaten und OEM-Sicherheitszertifikaten/Signierung.\n</li></ul>\n</li><li><strong>Deployment (Transfer-Pfad):</strong> \n<ul class=\"fig-list\"><li>Asynchrone Übertragung via Mobilfunk/Backend (OTA) oder leitungsgebunden über Diagnose-Protokolle (ISO 13400 / DoIP, ISO 14229-1 / UDS Dienst <code>0x34</code> / <code>0x36</code> / <code>0x37</code>) an das Steuergerät.\n</li></ul>\n</li><li><strong>Target-seitiges Entpacken &amp; Vorbereitung (On-Board):</strong>\n<ul class=\"fig-list\"><li><em>Phase 1:</em> Empfang des OEM-Archivs im Zwischenspeicher (<code>OTA/DM</code>). Authentifizierung und Integritätsprüfung des OEM-Pakets.\n</li><li><em>Phase 2:</em> Strippen/Entpacken des OEM-Containers; Isolierung des darin enthaltenen Vendor-Pakets.\n</li><li><em>Phase 3:</em> Übergabe des Vendor-Pakets an die interne UCM-Schnittstelle (<code>ara::ucm</code>) zur Aktivierung, Verifikation und atomaren Installation (A/B-Partitionierung oder In-Place-Update).\n</li></ul>\n</li></ol>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Trennung von Zuständigkeiten (Security &amp; Responsibility Separation):</strong> \n<ul class=\"fig-list\"><li>Entwickler müssen sicherstellen, dass Software-Artefakte strikt entkoppelt bleiben: Der Vendor signiert funktionale Komponenten; der OEM signiert die fahrzeugspezifische Ausrollung/Kampagne. Signaturen beider Ebenen dürfen sich nicht gegenseitig ungültig machen.\n</li></ul>\n</li><li><strong>Metadaten-Konsistenz (Software Package Manifest):</strong> \n<ul class=\"fig-list\"><li>Metadaten müssen den Schemata der AUTOSAR Adaptive Platform entsprechen. Abhängigkeiten (<code>SoftwareCluster</code>-Abhängigkeiten, Minimalversionen des Adaptive Core) müssen im Vendor-Manifest explizit deklariert sein, damit UCM vor der Aktivierung eine statische Kompatibilitätsprüfung durchführen kann.\n</li></ul>\n</li><li><strong>Ressourcenallokation auf Embedded Targets:</strong> \n<ul class=\"fig-list\"><li>Das zweistufige Container-Format (<code>tar</code>/<code>zip</code> in <code>tar</code>/<code>zip</code>) erfordert ausreichenden flüchtigen oder permanenten Staging-Speicher (mindestens 2× bis 3× der Paketgröße) für den zweistufigen Entpack- und Verifikationsprozess, falls kein Streaming-Dekompressor implementiert ist.\n</li></ul>\n</li><li><strong>UCM API-Vertrag:</strong> \n<ul class=\"fig-list\"><li>Das <code>OTA/DM</code>-Modul agiert typischerweise als Client des <code>ara::ucm::pkgmgr</code> (Package Management Interface). Das Vendor-Paket wird über Methoden wie <code>TransferData</code>, <code>ProcessSwPackage</code> und <code>Activate</code> verarbeitet. Entwickler müssen Fehlerpfade (z. B. Signaturfehler auf OEM-Ebene vs. Versionskonflikt auf Vendor-Ebene) differenziert über die UCM-Fehlercodes (<code>ara::core::ErrorCode</code>) abfangen.\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f463a5635f003bc7", "releases": ["R18-10-1", "R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Struktur- und Kapselungsdiagramm (Container-/Archivmodell) der AUTOSAR Adaptive Platform.\n</li><li><strong>Kontext &amp; Zweck:</strong> Veranschaulichung des internen hierarchischen Aufbaus eines Software Packages (<code>Software Package A</code>) für das Update and Configuration Management (UCM). Es definiert die Gruppierung der Software-Artefakte und des begleitenden Integrationsmanifests innerhalb der Paketdatei.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Software Package A (Äußerer Container):</strong>\n<ul class=\"fig-list\"><li>Umfassendes Archiv eines Software-Pakets, dargestellt als Dokumenten-/Datei-Container mit Eselsohr.\n</li></ul>\n</li><li><strong>Integrierter Nutzdaten- und Komponenten-Container (Innerer Container):</strong>\n<ul class=\"fig-list\"><li><strong>Executables:</strong> Ausführbare Binärdateien und Applikationsprogramme der Software-Komponenten/des Software-Clusters.\n</li><li><strong>Data:</strong> Statische Konfigurations-, Kalibrier- und Laufzeitdaten.\n</li><li><strong>Manifests:</strong> Untergeordnete Komponenten- bzw. Ausführungsbeschreibungen.\n</li></ul>\n</li><li><strong>Manifest-Artefakt:</strong>\n<ul class=\"fig-list\"><li><strong>SWCL Integration arxml:</strong> Spezifisches AUTOSAR-XML-Integrationsmanifest des Software-Clusters (SWCL) zur Steuerung und Beschreibung der Integration auf Systemebene.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Bündelung:</strong>\n<ul class=\"fig-list\"><li>Zusammenfassung der Artefakte (<code>Executables</code>, <code>Data</code>, <code>Manifests</code>) in einem strukturierten inneren Datenbereich.\n</li></ul>\n</li><li><strong>Kapselung mit Integrationsdeskriptor:</strong>\n<ul class=\"fig-list\"><li>Verknüpfung der komponentenbezogenen Daten mit dem Steuer- und Integrationsdokument <code>SWCL Integration arxml</code>.\n</li></ul>\n</li><li><strong>Paketabschluss:</strong>\n<ul class=\"fig-list\"><li>Kapselung der Gesamtheit aller Bestandteile im übergeordneten Auslieferungscontainer <code>Software Package A</code> zur Bereitstellung an UCM.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Paketkonformität:</strong> Ein Software Package muss als geschlossenes Archiv bereitgestellt werden, das neben den Programmdateien und Daten zwingend das <code>SWCL Integration arxml</code> zur Spezifikation der Integrationsparameter enthält.\n</li><li><strong>Archivaufbau:</strong> Entwickler und Integrationswerkzeuge müssen sicherstellen, dass Anwendungsdaten (<code>Data</code>, <code>Executables</code>, <code>Manifests</code>) strukturiert von den globalen Steuerungsmanifesten getrennt und auf Paketebene aggregiert werden.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-3078f15474a38eaa", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Struktur-, Kapselungs- und Sicherheitsdiagramm der AUTOSAR Adaptive Platform.\n</li><li><strong>Kontext &amp; Zweck:</strong> Veranschaulichung des Sicherheits- und Kapselungsaufbaus eines Software Packages (<code>Software Package A</code>) im Update and Configuration Management (UCM). Das Diagramm spezifiziert die Integritäts- und Authentizitätssicherung mittels digitaler Signatur über die enthaltenen Nutzdaten und das zentrale Paketmanifest.\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Software Package A (Übergeordneter Container):</strong>\n<ul class=\"fig-list\"><li>Äußerer Archivcontainer, der die kryptografische Signatur und den gesicherten Inhaltscontainer umfasst.\n</li></ul>\n</li><li><strong>Signed container:</strong>\n<ul class=\"fig-list\"><li>Logische Kapsel der zu signierenden Nutzlast und Metadaten, über welche die Signatur gebildet wird.\n</li><li><strong>Nutzdaten-Block (Innerer Container):</strong>\n<ul class=\"fig-list\"><li><strong>Executables:</strong> Ausführbare Binärdateien und Anwendungsprogramme.\n</li><li><strong>Data:</strong> Anwendungs- und Konfigurationsdaten.\n</li><li><strong>Manifests:</strong> Komponentenspezifische Manifestdateien.\n</li></ul>\n</li><li><strong>Software Package Manifest:</strong>\n<ul class=\"fig-list\"><li>Zentrales AUTOSAR-XML-Manifest des Software-Pakets, das Metadaten, Validierungsregeln und Abhängigkeiten für UCM deklariert.\n</li></ul>\n</li></ul>\n</li><li><strong>Sicherheitsentität:</strong>\n<ul class=\"fig-list\"><li><strong>Signature:</strong> Kryptografische Signatur (Digital Signature) zur Verifikation der Authentizität und Unversehrtheit des <code>Signed container</code>.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Archiverstellung &amp; Aggregation:</strong>\n<ul class=\"fig-list\"><li>Bündelung der Software-Bestandteile (<code>Executables</code>, <code>Data</code>, <code>Manifests</code>) sowie des zentralen <code>Software Package Manifest</code> innerhalb des zu signierenden Bereichs (<code>Signed container</code>).\n</li></ul>\n</li><li><strong>Kryptografische Signierung:</strong>\n<ul class=\"fig-list\"><li>Berechnung des Hashwerts über den <code>Signed container</code> und Generierung der Signatur (<code>Signature</code>) mittels privatem Schlüssel.\n</li></ul>\n</li><li><strong>Finalisierung des Gesamtpakets:</strong>\n<ul class=\"fig-list\"><li>Zusammenfügen von <code>Signed container</code> und <code>Signature</code> in das finale <code>Software Package A</code>.\n</li></ul>\n</li><li><strong>Verifikation auf der Zielplattform:</strong>\n<ul class=\"fig-list\"><li>Das Steuergerät (UCM) prüft vor Entpacken oder Aktivieren der Artefakte die Signatur gegen den <code>Signed container</code> unter Nutzung hinterlegter öffentlicher Schlüssel bzw. Zertifikate.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Sicherheitsanforderung:</strong> Jedes <code>Software Package A</code> erfordert eine digitale Signatur, die den Inhalt des <code>Signed container</code> absichert.\n</li><li><strong>Manifest-Standardisierung:</strong> Das Paketmanifest ist als <code>Software Package Manifest</code> normiert und Bestandteil des signierten Containers.\n</li><li><strong>Validierungssequenz:</strong> Zielsysteme dürfen <code>Executables</code>, <code>Data</code> und <code>Manifests</code> erst nach erfolgreicher Validierung der <code>Signature</code> über den <code>Signed container</code> entpacken oder zur Ausführung bringen.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2d0c27016d1b24fc", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Struktur-, Kapselungs- und Sicherheitsdiagramm der AUTOSAR Adaptive Platform.\n</li><li><strong>Kontext &amp; Zweck:</strong> Veranschaulichung des Kapselungs- und Authentifizierungsmodells eines Software Packages (<code>Software Package A</code>) für das Update and Configuration Management (UCM). Das Diagramm definiert den Schutz der Software-Inhalte über einen Authentication Tag (z. B. im Rahmen von Authenticated Encryption oder MAC-Verfahren).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Software Package A (Übergeordneter Container):</strong>\n<ul class=\"fig-list\"><li>Äußerer Container für das auszuliefernde Software-Paket.\n</li></ul>\n</li><li><strong>Signed container:</strong>\n<ul class=\"fig-list\"><li>Logischer Container der abgesicherten Artefakte.\n</li><li><strong>Nutzdaten-Block (Innerer Container):</strong>\n<ul class=\"fig-list\"><li><strong>Executables:</strong> Binärdateien und Programmcode.\n</li><li><strong>Data:</strong> Konfigurations- und Nutzdaten.\n</li><li><strong>manifests:</strong> Detaillierte Ausführungs- und Komponentenmanifeste.\n</li></ul>\n</li><li><strong>Software Package manifest:</strong>\n<ul class=\"fig-list\"><li>Zentrales Metadaten- und Steuerungsmanifest des Software-Pakets.\n</li></ul>\n</li></ul>\n</li><li><strong>Sicherheitsentität:</strong>\n<ul class=\"fig-list\"><li><strong>Authentication tag:</strong> Authentifizierungstag (z. B. MAC oder AEAD-Tag) zur Verifikation der Integrität und Authentizität des geschützten Containers.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Paketzusammenstellung:</strong>\n<ul class=\"fig-list\"><li>Strukturierung von <code>Executables</code>, <code>Data</code>, <code>manifests</code> und dem <code>Software Package manifest</code> im <code>Signed container</code>.\n</li></ul>\n</li><li><strong>Authentifizierungsschutz:</strong>\n<ul class=\"fig-list\"><li>Erzeugung des <code>Authentication tag</code> über den Containerinhalt.\n</li></ul>\n</li><li><strong>Verpackung:</strong>\n<ul class=\"fig-list\"><li>Kapselung von <code>Signed container</code> und <code>Authentication tag</code> in <code>Software Package A</code>.\n</li></ul>\n</li><li><strong>On-Board-Prüfung:</strong>\n<ul class=\"fig-list\"><li>Vor Verarbeitung der Anwendungsbestandteile verifiziert UCM den <code>Authentication tag</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Integritätsnachweis:</strong> Die Authentizität und Unverfälschtheit des Pakets wird über einen <code>Authentication tag</code> auf Paketebene nachgewiesen.\n</li><li><strong>Kapselungskonformität:</strong> Die Komponenten <code>Executables</code>, <code>Data</code>, <code>manifests</code> und <code>Software Package manifest</code> müssen vollständig im signierten/authentifizierten Container gekapselt sein.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2a153215769677e8", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Klassifikation:</strong> Struktur-, Kapselungs- und Sicherheitsdiagramm der AUTOSAR Adaptive Platform.\n</li><li><strong>Kontext &amp; Zweck:</strong> Veranschaulichung des Kapselungs- und Authentifizierungsmodells eines Software Packages (<code>Software Package A</code>) für das Update and Configuration Management (UCM). Das Diagramm definiert den Schutz der Software-Inhalte über einen Authentication Tag (z. B. im Rahmen von Authenticated Encryption oder MAC-Verfahren).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Software Package A (Übergeordneter Container):</strong>\n<ul class=\"fig-list\"><li>Äußerer Container für das auszuliefernde Software-Paket.\n</li></ul>\n</li><li><strong>Signed container:</strong>\n<ul class=\"fig-list\"><li>Logischer Container der abgesicherten Artefakte.\n</li><li><strong>Nutzdaten-Block (Innerer Container):</strong>\n<ul class=\"fig-list\"><li><strong>Executables:</strong> Binärdateien und Programmcode.\n</li><li><strong>Data:</strong> Konfigurations- und Nutzdaten.\n</li><li><strong>Manifests:</strong> Detaillierte Ausführungs- und Komponentenmanifeste.\n</li></ul>\n</li><li><strong>Software Package Manifest:</strong>\n<ul class=\"fig-list\"><li>Zentrales Metadaten- und Steuerungsmanifest des Software-Pakets.\n</li></ul>\n</li></ul>\n</li><li><strong>Sicherheitsentität:</strong>\n<ul class=\"fig-list\"><li><strong>Authentication tag:</strong> Authentifizierungstag zur Verifikation der Integrität und Authentizität des geschützten Containers.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li><strong>Paketzusammenstellung:</strong>\n<ul class=\"fig-list\"><li>Strukturierung von <code>Executables</code>, <code>Data</code>, <code>manifests</code> und dem <code>Software Package manifest</code> im <code>Signed container</code>.\n</li></ul>\n</li><li><strong>Authentifizierungsschutz:</strong>\n<ul class=\"fig-list\"><li>Erzeugung des <code>Authentication tag</code> über den Containerinhalt.\n</li></ul>\n</li><li><strong>Verpackung:</strong>\n<ul class=\"fig-list\"><li>Kapselung von <code>Signed container</code> und <code>Authentication tag</code> in <code>Software Package A</code>.\n</li></ul>\n</li><li><strong>On-Board-Prüfung:</strong>\n<ul class=\"fig-list\"><li>Vor Verarbeitung der Anwendungsbestandteile verifiziert UCM den <code>Authentication tag</code>.\n</li></ul>\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Integritätsnachweis:</strong> Die Authentizität und Unverfälschtheit des Pakets wird über einen <code>Authentication tag</code> auf Paketebene nachgewiesen.\n</li><li><strong>Kapselungskonformität:</strong> Die Komponenten <code>Executables</code>, <code>Data</code>, <code>manifests</code> und <code>Software Package manifest</code> müssen vollständig im signierten/authentifizierten Container gekapselt sein.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-231030c70bd5ffec", "to": "FIG-f463a5635f003bc7", "fr": "R18-03_R1.4.0", "tr": "R18-10-1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Diagramminhalt &amp; Fokus vollständig geändert</strong>: Das bisherige Prozess- und Pipeline-Diagramm zur Software-Paketierung (Vendor -&gt; OEM -&gt; OTA/DM) wurde durch ein Schichten- bzw. Kapselungsmodell der internen Paketstruktur (<code>Software Package A</code>) ersetzt.\n</li><li><strong>Entfallene Elemente</strong>: Tooling-Bereich mit <code>Vendor</code>- und <code>OEM</code>-Stufe, Deployment-Pfad sowie Zielsystem-Bereich (<code>Target</code>, <code>OTA/DM</code>).\n</li><li><strong>Neue Container-Hierarchie</strong>: <code>Software Package A</code> als übergeordneter Container, der einen inneren Container mit <code>Executables</code>, <code>Data</code> und <code>Manifests</code> sowie das Manifest <code>SWCL Integration arxml</code> kapselt.\n</li></ul>"}, {"from": "FIG-f463a5635f003bc7", "to": "FIG-3078f15474a38eaa", "fr": "R18-10_R4.4.0_R1.5.0", "tr": "R19-03", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Signatur- und Sicherheitskapselung hinzugefügt</strong>: Einführung eines geschachtelten <code>Signed container</code>, der die Nutzdatenblöcke (<code>Executables</code>, <code>Data</code>, <code>Manifests</code>) sowie das umbenannte <code>Software Package Manifest</code> umschließt.\n</li><li><strong>Sicherheitselement ergänzt</strong>: Hinzufügung eines separaten <code>Signature</code>-Blocks innerhalb von <code>Software Package A</code> unterhalb des <code>Signed container</code>.\n</li><li><strong>Manifest umbenannt</strong>: <code>SWCL Integration arxml</code> wurde in <code>Software Package Manifest</code> umbenannt.\n</li></ul>"}, {"from": "FIG-3078f15474a38eaa", "to": "FIG-2d0c27016d1b24fc", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><strong>Sicherheitsmechanismus geändert</strong>: Der Signaturblock <code>Signature</code> wurde durch <code>Authentication tag</code> ersetzt.\n</li><li><strong>Schreibweise Manifeste</strong>: <code>Manifests</code> im inneren Block und <code>Software Package Manifest</code> wurden redaktionell auf Kleinschreibung (<code>manifests</code>, <code>Software Package manifest</code>) angepasst.\n</li></ul>"}, {"from": "FIG-2d0c27016d1b24fc", "to": "FIG-2a153215769677e8", "fr": "R19-11", "tr": "R20-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><strong>Schreibweise angepasst</strong>: <code>manifests</code> wurde wieder zu <code>Manifests</code> und <code>Software Package manifest</code> wieder zu <code>Software Package Manifest</code> großgeschrieben.\n</li><li><strong>Farbanpassung</strong>: Der Hintergrund des Blocks <code>Authentication tag</code> wurde von hellem Blau zu dunklem Blau geändert.\n</li></ul>"}]};
